mapper.select:
SELECT id, group_id, name
FROM series
WHERE user_id = #{userId} AND id = #{id}

SELECT id, group_id, name
FROM series
WHERE user_id = #{userId} AND group_id = #{parentId} AND name = #{name}

SELECT COUNT(*)
FROM series
WHERE user_id = #{userId} AND group_id = #{parentId}

SELECT COUNT(DISTINCT figure_id)
FROM figure_series
WHERE user_id = #{userId} AND series_id = #{id}

mapper.insert:
INSERT INTO figure_series (user_id, figure_id, series_id)
SELECT DISTINCT l.user_id, l.figure_id, #{fallbackId}
FROM figure_series l
WHERE l.user_id = #{userId}
  AND l.series_id = #{id}
  AND NOT EXISTS (
      SELECT 1 FROM figure_series o
      WHERE o.user_id = l.user_id AND o.figure_id = l.figure_id
        AND o.series_id <> #{id}
  )
